/// Computes the triangular number T(n) = 1 + 2 + … + n, with T(0) = 0,
/// by repeatedly “advancing” from `idx` up to `n`, accumulating in `sum`.
///
/// Preconditions:
/// - `idx <= n`
/// - `*sum` initially == T(idx)
/// - T(n) < 2^32 (so no overflow occurs)
pub fn tail_triangle(n: u32, mut idx: u32, sum: &mut u32) {
    // While we haven't reached the target index `n`,
    // step `idx` forward by 1 and add it into `*sum`.
    while idx < n {
        idx += 1;
        *sum += idx;
    }
}

/// A convenient wrapper that computes T(n) from 0 to n.
pub fn triangle(n: u32) -> u32 {
    let mut acc = 0;
    tail_triangle(n, 0, &mut acc);
    acc
}

